"""Offline fixture ENCODER only. Never builds/runs the packet decoder/tests.

Requires ffmpeg with the native AAC encoder on PATH. All samples are created
here; no app/downloaded/copyrighted stream is used. Check in the emitted bytes
so normal tests do not require Python, FFmpeg CLI, demux, or filesystem access.
"""
import hashlib
import math
from pathlib import Path
import shutil
import struct
import subprocess
import wave

root = Path(__file__).resolve().parent
ffmpeg = shutil.which("ffmpeg")
if not ffmpeg:
    raise SystemExit("ffmpeg encoder not found")
rate = 48000
samples = 5 * 1024
pcm = bytearray()
for i in range(samples):
    for frequency in (440, 880):
        pcm.extend(struct.pack("<h", round(8192 * math.sin(2 * math.pi * frequency * i / rate))))
with wave.open(str(root / "source.wav"), "wb") as wav:
    wav.setnchannels(2)
    wav.setsampwidth(2)
    wav.setframerate(rate)
    wav.writeframes(pcm)
subprocess.run([
    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
    "-i", str(root / "source.wav"), "-map_metadata", "-1",
    "-c:a", "aac", "-profile:a", "aac_low", "-b:a", "192k",
    "-threads", "1", "-flags:a", "+bitexact", "-f", "adts", str(root / "tone.aac")
], check=True)
data = (root / "tone.aac").read_bytes()
packets = []
offset = 0
while offset < len(data):
    length = ((data[offset + 3] & 3) << 11) | (data[offset + 4] << 3) | (data[offset + 5] >> 5)
    if data[offset] != 255 or length < 7 or offset + length > len(data):
        raise SystemExit("encoder emitted invalid ADTS")
    packets.append(data[offset:offset + length])
    offset += length
lines = ["// Purpose-generated by generate.py; stereo 440/880 Hz, 48 kHz AAC-LC ADTS.",
         "#pragma once", "#include <array>", "#include <cstdint>", "#include <span>",
         "namespace EsvmAacFixture {"]
for index, packet in enumerate(packets):
    lines.append(f"inline constexpr std::array<uint8_t, {len(packet)}> Packet{index} {{")
    for start in range(0, len(packet), 16):
        lines.append("\t" + ", ".join(f"0x{b:02x}" for b in packet[start:start + 16]) + ",")
    lines.append("};")
lines.append(f"inline constexpr std::array<std::span<const uint8_t>, {len(packets)}> Packets {{")
lines.append("\t" + ", ".join(f"Packet{i}" for i in range(len(packets))))
lines.extend(["};", "} // namespace EsvmAacFixture", ""])
(root / "packets.h").write_text("\n".join(lines), encoding="utf-8")
print("Encoder:", subprocess.check_output([ffmpeg, "-version"], text=True).splitlines()[0])
print("Packets:", [len(packet) for packet in packets])
print("SHA256:", hashlib.sha256(data).hexdigest())
